const open = async () => {
    const showIntro = !onboardingSeen
    if (showIntro) {
      try {
        await mobile.configure({ onboardingSeen: true })
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error)
        context.toast('Could not update Mobile onboarding', message, { kind: 'error' })
      }
    }
    context.openView(MOBILE_PAGE_ID, showIntro ? { stage: 'intro' } : undefined)
  }

const revoke = async (device: MobileDevice) => {
    setBusyDevice(device.deviceId)
    setNotice(null)
    setError(null)
    try {
      await revokeMobileDevice(context, device.deviceId)
      setNotice('Device revoked.')
      try {
        await onChanged()
      } catch (reason) {
        const message = reason instanceof Error ? reason.message : String(reason)
        setNotice(null)
        setError(`Device revoked, but the paired-device list could not refresh: ${message}`)
      }
    } catch (reason) {
      const message = reason instanceof Error ? reason.message : String(reason)
      setNotice(null)
      setError(`Failed to revoke device: ${message}`)
    } finally {
      setBusyDevice(null)
    }
  }

export async function revokeMobileDevice(context: UiPluginContext, deviceId: string): Promise<void> {
  const result = (await context.call('quirky.mobile/revoke', { deviceId })) as { revoked: boolean }
  if (!result.revoked) throw new Error('Device is no longer paired.')
}

